def transform(grid):
    """Mark the clipped right edge of a less-complete repeated pattern with 1."""
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    foreground = max((v for v in counts if v != bg), key=lambda v: counts[v])
    out = [row[:] for row in grid]

    # Foreground-bearing consecutive rows make an instance; blank rows
    # separate repeated instances.
    blocks = []
    r = 0
    while r < h:
        if foreground in grid[r]:
            start = r
            while r < h and foreground in grid[r]:
                r += 1
            blocks.append(list(range(start, r)))
        else:
            r += 1

    def amount(block):
        return sum(grid[rr][c] == foreground for rr in block for c in range(w))

    # Find the strongest same-height pair: one complete exemplar and one
    # instance with a truncated right side. In single-row examples this
    # simply pairs a full bar with its shorter prefix.
    pairs = []
    for source in blocks:
        for target in blocks:
            if source is target or len(source) != len(target):
                continue
            missing = amount(source) - amount(target)
            if missing > 0:
                pairs.append((missing, amount(source), -source[0], source, target))
    if not pairs:
        return out

    _, _, _, source, target = max(pairs, key=lambda p: p[:3])
    # The common right cutoff is just beyond the furthest colored cell in
    # the clipped instance. Only copy exemplar foreground beyond that cutoff.
    cutoff = max(
        max((c for c, value in enumerate(grid[rr]) if value == foreground), default=-1)
        for rr in target
    ) + 1
    for sr, tr in zip(source, target):
        for c in range(cutoff, w):
            if grid[sr][c] == foreground and grid[tr][c] == bg:
                out[tr][c] = 1
    return out

